// Preserve each native local rest translation and apply source animation deltas.
// Quaternion channels copy directly because bone axes and hierarchy are unchanged.
function retargetClip(clip,rig,common=DATA.commonRig){const next=clip.clone(),norm=s=>s.replace(/[. _]/g,'');for(const t of next.tracks){if(!t.name.endsWith('.position'))continue;const name=norm(t.name.slice(0,-9).replace(/^.*\]/,'')),i=common.joints.findIndex(j=>norm(j.name)===name);if(i<0)throw Error('unknown animated position '+t.name);const a=common.joints[i],b=rig.joints[i],ap=a.parent<0?[0,0,0]:common.joints[a.parent].worldRest,bp=b.parent<0?[0,0,0]:rig.joints[b.parent].worldRest,ar=a.worldRest.map((v,k)=>v-ap[k]),br=b.worldRest.map((v,k)=>v-bp[k]),head=[4,5].includes(i),q=rig.proportions;for(let j=0;j<t.values.length;j+=3)for(let k=0;k<3;k++){const scale=k===1?(head?q.headY:q.bodyY):(head?q.headXZ:1);t.values[j+k]=br[k]+(t.values[j+k]-ar[k])*scale;}}return next;}

function match(look={}){return DATA.characters.find(c=>Object.entries(c.items).every(([slot,id])=>look[slot]===id))||null;}
return {characters:DATA.characters,commonRig:DATA.commonRig,match,retargetClip};
